class Solution {
    public int magnificentSets(int n,int[][] edges){
        List<Integer>[] graph=new ArrayList[n];
        for(int i=0;i<n;i++)graph[i]=new ArrayList<>();
        for(int[] edge:edges){
            graph[edge[0]-1].add(edge[1]-1);
            graph[edge[1]-1].add(edge[0]-1);
        }
        int[] color=new int[n];
        Arrays.fill(color,-1);
        int answer=0;
        for(int root=0;root<n;root++)if(color[root]<0){
            List<Integer> component=new ArrayList<>();
            Deque<Integer> queue=new ArrayDeque<>();
            queue.offer(root);
            color[root]=0;
            while(!queue.isEmpty()){
                int node=queue.poll();
                component.add(node);
                for(int next:graph[node]){
                    if(color[next]<0){
                        color[next]=color[node]^1;
                        queue.offer(next);
                    }else if(color[next]==color[node])return -1;
                }
            }
            int best=0;
            for(int start:component){
                int[] distance=new int[n];
                Arrays.fill(distance,-1);
                queue.offer(start);
                distance[start]=0;
                int farthest=0;
                while(!queue.isEmpty()){
                    int node=queue.poll();
                    for(int next:graph[node])if(distance[next]<0){
                        distance[next]=distance[node]+1;
                        farthest=Math.max(farthest,distance[next]);
                        queue.offer(next);
                    }
                }
                best=Math.max(best,farthest+1);
            }
            answer+=best;
        }
        return answer;
    }
}

